// Photographic money rain at 60% opacity - real bills, dreamy fall
// Cal's licensed $100 bill, embedded flat - the 3D flex animation
// does the bending, so every fall looks a little different
const BILL_IMAGES = [
  "data:image/webp;base64,",
];

function PhotoRain() {
  // Rain that lives INSIDE the photo frame — clipped by the frame's
  // rounded edges so the money appears to fall within the scene itself
  // Denser rain: more bills in the air at once, staggered so the
  // downpour never has an empty moment
  const pieces = Array.from({ length: 14 }, (_, i) => {
    const img = BILL_IMAGES[i % BILL_IMAGES.length];
    const left = Math.random() * 94;
    const delay = Math.random() * 6;
    const duration = 6 + Math.random() * 5; // half speed - a lazy, dreamy fall
    const size = 48 + Math.random() * 30; // bill width in px
    const drift = -24 + Math.random() * 48;
    const tilt = -18 + Math.random() * 36; // leans a bit more while staying broadly upright
    const flip = Math.random() > 0.5 ? -1 : 1; // mirror half for variety
    const flutter = 1.9 + Math.random() * 2.2; // each bill flexes at its own pace
    return { img, left, delay, duration, size, drift, tilt, flip, flutter, key: i };
  });
  return (
    <div aria-hidden="true" style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex: 2, perspective: "500px" }}>
      {pieces.map((p) => (
        <span
          key={p.key}
          style={{
            position: "absolute",
            top: "-130px",
            left: `${p.left}%`,
            lineHeight: 0,
            filter: "drop-shadow(0 3px 4px rgba(0,0,0,0.25))",
            animation: `rainFallPhoto ${p.duration}s linear ${p.delay}s infinite`,
            "--drift": `${p.drift}px`,
            "--tilt": `${p.tilt}deg`,
          }}
        >
          <img
            src={p.img}
            alt=""
            style={{
              width: p.size,
              display: "block",
              animation: `billFlex ${p.flutter}s ease-in-out ${p.delay}s infinite alternate`,
              "--flip": p.flip,
            }}
          />
        </span>
      ))}
    </div>
  );
}

// A free, no-login interactive chart page for the given symbol (TradingView).
function chartUrl(sym) {
  const s = String(sym || "").toUpperCase();
  if (s === "BTC" || s === "BITCOIN") return "https://www.tradingview.com/symbols/BTCUSD/";
  return "https://www.tradingview.com/symbols/" + encodeURIComponent(s) + "/";
}
function ChartLink({ sym }) {
  const s = String(sym || "").toUpperCase();
  return (
    <a
      href={chartUrl(s)}
      target="_blank"
      rel="noopener noreferrer"
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 8,
        fontFamily: "'Outfit', sans-serif",
        fontWeight: 700,
        fontSize: 14.5,
        color: palette.oceanDark,
        textDecoration: "none",
        background: "rgba(255,255,255,0.9)",
        border: `2px solid ${palette.ocean}`,
        borderRadius: 999,
        padding: "10px 20px",
      }}
    >
      {"📈"} View live chart for {s} {"↗"}
    </a>
  );
}

// Shared signed-score helpers for the sentiment sliders:
// internal 0-100 value -> displayed -50 ... 0 ... +50
function signedScore(value) {
  const pct = Math.max(0, Math.min(100, value));
  return Math.round(pct) - 50;
}
function signedLabel(score) {
  return score > 0 ? "+" + score : String(score);
}
function signedColor(score) {
  return score > 0 ? palette.palm : score < 0 ? palette.red : palette.ink;
}
function TensionBar({ value }) {
  // value: 0 (all bear) → 100 (all bull)
  const pct = Math.max(0, Math.min(100, value));
  return (
    <div style={{ margin: "8px 0 4px" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-end",
          fontFamily: "'Outfit', sans-serif",
          fontSize: 13,
          fontWeight: 600,
          color: palette.ink,
          marginBottom: 6,
        }}
      >
        <span style={{ flex: 1, textAlign: "left", color: palette.coralDark }}>Reasons to worry</span>
        <span
          style={{
            fontFamily: "'Fraunces', serif",
            fontWeight: 900,
            fontSize: 22,
            lineHeight: 1,
            color: signedColor(signedScore(value)),
          }}
        >
          {signedLabel(signedScore(value))}
        </span>
        <span style={{ flex: 1, textAlign: "right", color: palette.palm }}>Reasons to be hopeful</span>
      </div>
      <div
        style={{
          height: 14,
          borderRadius: 999,
          background: `linear-gradient(90deg, ${palette.coral}, ${palette.sandDeep} 50%, ${palette.palm})`,
          position: "relative",
          boxShadow: "inset 0 1px 3px rgba(0,0,0,0.15)",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: -5,
            left: `calc(${pct}% - 12px)`,
            width: 24,
            height: 24,
            borderRadius: "50%",
            background: palette.white,
            border: `3px solid ${palette.ink}`,
            boxShadow: "0 2px 6px rgba(0,0,0,0.25)",
            transition: "left 0.8s cubic-bezier(.2,.8,.2,1)",
          }}
        />
      </div>
    </div>
  );
}

