function MaxPainBox({ sym, getMaxPain, getWeeklyMaxPain }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  // Expandable weekly breakdown (next ~4 Friday expirations).
  const [expanded, setExpanded] = useState(false);
  const [weeks, setWeeks] = useState(null);
  const [wLoading, setWLoading] = useState(false);
  const [wError, setWError] = useState(false);
  const load = async () => {
    setLoading(true);
    setError(false);
    try {
      const d = await getMaxPain(sym);
      if (!d || typeof d.maxPain !== "number") throw new Error("no data");
      setData(d);
    } catch (e) {
      setError(true);
    } finally {
      setLoading(false);
    }
  };
  const loadWeeks = async () => {
    if (!getWeeklyMaxPain) return;
    setWLoading(true);
    setWError(false);
    try {
      const d = await getWeeklyMaxPain(sym);
      const list = (d && Array.isArray(d.weeks) ? d.weeks : []).filter((w) => typeof w.maxPain === "number");
      if (!list.length) throw new Error("no weeks");
      setWeeks({ spot: typeof d.spot === "number" ? d.spot : (data && data.spot) || null, list });
    } catch (e) {
      setWError(true);
    } finally {
      setWLoading(false);
    }
  };
  const toggleExpand = () => {
    const next = !expanded;
    setExpanded(next);
    if (next && !weeks && !wLoading) loadWeeks();
  };
  useEffect(() => {
    if (sym) load();
    // Reset the weekly view whenever the ticker changes.
    setExpanded(false); setWeeks(null); setWError(false);
  }, [sym]);
  if (error) return null;
  const spot = data && typeof data.spot === "number" ? data.spot : null;
  const rel =
    data && spot != null
      ? data.maxPain < spot
        ? "below today's price"
        : data.maxPain > spot
        ? "above today's price"
        : "right about where it's trading"
      : null;
  return (
    <div style={{ marginTop: 26 }}>
      <h3
        style={{
          fontFamily: "'Fraunces', serif",
          fontWeight: 700,
          fontSize: 20,
          color: palette.ink,
          margin: "0 0 8px",
        }}
      >
        {"🎯"} Max pain
      </h3>
      {loading ? (
        <div
          style={{
            fontFamily: "'Outfit', sans-serif",
            fontSize: 14.5,
            color: palette.oceanDark,
            background: "rgba(255,255,255,0.75)",
            borderRadius: 12,
            padding: "14px 18px",
          }}
        >
          Crunching the live options chain{"…"}
        </div>
      ) : data ? (
        <div
          style={{
            background: "rgba(255,255,255,0.85)",
            borderRadius: 14,
            padding: "16px 18px",
            borderLeft: "5px solid #D9A400",
          }}
        >
          <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
            <span
              style={{
                fontFamily: "'Fraunces', serif",
                fontWeight: 900,
                fontSize: 34,
                lineHeight: 1,
                color: palette.oceanDark,
              }}
            >
              ${data.maxPain}
            </span>
            {spot != null && (
              <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 14, color: palette.ink, opacity: 0.85 }}>
                vs. ${spot.toFixed(2)} now {"—"} the pull sits {rel}
              </span>
            )}
          </div>
          <p
            style={{
              fontFamily: "'Outfit', sans-serif",
              fontSize: 14.5,
              color: palette.ink,
              lineHeight: 1.55,
              margin: "10px 0 0",
            }}
          >
            The price where the most options would expire worthless{" "}
            {data.expiration ? `around the ${data.expiration} expiration` : "for the nearest monthly expiration"}
            . It{"’"}s where options math tends to tug a stock as expiration nears {"—"} a gentle gravity, not a prediction.
          </p>
          <div style={{ display: "flex", gap: 10, alignItems: "center", marginTop: 12, flexWrap: "wrap" }}>
            <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 12, color: palette.ink, opacity: 0.6 }}>
              from current options positioning
            </span>
            {getWeeklyMaxPain && (
              <button
                onClick={toggleExpand}
                style={{
                  fontFamily: "'Outfit', sans-serif", fontWeight: 700, fontSize: 12.5, color: palette.oceanDark,
                  background: "rgba(14,116,144,0.1)", border: `1.5px solid ${palette.ocean}`, borderRadius: 999,
                  padding: "6px 14px", cursor: "pointer", marginLeft: "auto",
                }}
              >
                {expanded ? "Hide weekly ▲" : "Expand · next 4 Fridays ▾"}
              </button>
            )}
          </div>

          {expanded && (
            <div style={{ marginTop: 12 }}>
              {wLoading ? (
                <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 13.5, color: palette.oceanDark, background: "rgba(255,255,255,0.7)", borderRadius: 10, padding: "12px 14px" }}>
                  Crunching the weekly chains{"…"}
                </div>
              ) : wError ? (
                <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 13, color: palette.coralDark, background: "rgba(255,255,255,0.7)", borderRadius: 10, padding: "12px 14px", lineHeight: 1.45 }}>
                  Couldn{"’"}t load the weekly breakdown. {sym} may not have weekly options, or the data-server update isn{"’"}t live yet.
                </div>
              ) : weeks && weeks.list.length ? (
                <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                  {weeks.list.map((w, i) => {
                    let label = w.expiration;
                    try { label = new Date(w.expiration + "T12:00:00").toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }); } catch (e) {}
                    return (
                      <div key={w.expiration || i} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", background: "rgba(255,255,255,0.8)", borderRadius: 10, padding: "10px 14px", borderLeft: "4px solid #D9A400" }}>
                        <span style={{ fontFamily: "'Outfit', sans-serif", fontWeight: 600, fontSize: 13.5, color: palette.ink }}>
                          {label}{i === 0 ? " · this week" : ""}
                        </span>
                        <span style={{ fontFamily: "'Fraunces', serif", fontWeight: 900, fontSize: 18, color: palette.oceanDark }}>
                          ${w.maxPain}
                        </span>
                      </div>
                    );
                  })}
                  <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 11.5, color: palette.ink, opacity: 0.6, marginTop: 2 }}>
                    Max pain per weekly expiration{weeks.spot != null ? ` · ${sym} ~$${weeks.spot.toFixed(2)} now` : ""}
                  </span>
                </div>
              ) : null}
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

function WatchRow({ item, onPick, onRemove, reorderable, isReordering, onReorderStart, onReorderMove, onReorderEnd }) {
  const [dx, setDx] = useState(0);
  const [dragging, setDragging] = useState(false);
  const startX = useRef(null);
  const moved = useRef(false);
  const canSwipe = !!onRemove && !item.gold;
  // Judge up/down on the ROUNDED figure, so a hair below zero doesn't render as
  // a red "▼-0.00%" — common on quiet after-hours moves.
  const pctDigits = item.gold ? 1 : 2;
  const pct = typeof item.changePct === "number" ? Number(item.changePct.toFixed(pctDigits)) : null;
  const flat = pct === 0;
  const up = pct != null ? pct >= 0 : (typeof item.change === "number" ? item.change >= 0 : null);
  const changeColor = up == null || flat ? palette.ink : up ? palette.palm : palette.red;
  const priceText =
    typeof item.price === "number"
      ? item.gold
        ? "$" + Math.round(item.price).toLocaleString()
        : "$" + item.price.toFixed(2)
      : null;
  const onDown = (e) => {
    if (!canSwipe) return;
    startX.current = e.clientX;
    moved.current = false;
    setDragging(true);
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) {}
  };
  const onMove = (e) => {
    if (startX.current == null) return;
    const d = e.clientX - startX.current;
    if (Math.abs(d) > 6) moved.current = true;
    setDx(Math.max(-104, Math.min(0, d)));
  };
  const onUp = () => {
    if (startX.current == null) return;
    const shouldDelete = dx < -64;
    startX.current = null;
    setDragging(false);
    if (shouldDelete) { onRemove(item.ticker); return; }
    setDx(0);
  };
  const handleClick = () => {
    if (moved.current) { moved.current = false; return; }
    onPick(item.ticker);
  };
  return (
    <div data-wl-row style={{ position: "relative", borderRadius: 12, overflow: isReordering ? "visible" : "hidden", zIndex: isReordering ? 5 : "auto" }}>
      {canSwipe && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: `linear-gradient(90deg, ${palette.coral}, ${palette.coralDark})`,
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            paddingRight: 16,
            borderRadius: 12,
          }}
        >
          <span style={{ fontFamily: "'Outfit', sans-serif", fontWeight: 800, fontSize: 13, color: "#fff" }}>Delete</span>
        </div>
      )}
      <div
        onClick={handleClick}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={onUp}
        onPointerCancel={onUp}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 10,
          background: item.gold ? "linear-gradient(180deg, #FFF6E0, #FBE6B0)" : palette.white,
          border: `1.5px solid ${item.gold ? "#D9A400" : "rgba(14,116,144,0.22)"}`,
          borderRadius: 12,
          padding: "6px 12px",
          cursor: "pointer",
          transform: `translateX(${dx}px)`,
          transition: dragging || isReordering ? "none" : "transform 0.18s ease",
          touchAction: "pan-y",
          userSelect: "none",
          boxShadow: isReordering ? "0 8px 22px rgba(0,0,0,0.28)" : "none",
        }}
      >
        {reorderable && !item.gold && (
          <div
            onPointerDown={(e) => { e.stopPropagation(); try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) {} onReorderStart && onReorderStart(item.ticker, e.clientY, e.currentTarget); }}
            onPointerMove={(e) => { e.stopPropagation(); onReorderMove && onReorderMove(e.clientY); }}
            onPointerUp={(e) => { e.stopPropagation(); onReorderEnd && onReorderEnd(); }}
            onPointerCancel={(e) => { e.stopPropagation(); onReorderEnd && onReorderEnd(); }}
            onClick={(e) => e.stopPropagation()}
            aria-label="Drag to reorder"
            title="Drag to reorder"
            style={{
              flexShrink: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              width: 20,
              marginLeft: -4,
              alignSelf: "stretch",
              color: palette.oceanDark,
              opacity: 0.45,
              cursor: "grab",
              touchAction: "none",
              fontSize: 17,
              lineHeight: 1,
            }}
          >
            {"⠿"}
          </div>
        )}
        <div
          style={{
            width: 30,
            height: 30,
            borderRadius: 8,
            background: item.gold ? "#F7C948" : palette.white,
            border: "1px solid rgba(0,0,0,0.08)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            overflow: "hidden",
            flexShrink: 0,
          }}
        >
          {item.gold ? (
            <span style={{ fontSize: 17 }}>{"₿"}</span>
          ) : item.logo ? (
            <img src={item.logo} alt="" draggable={false} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
          ) : (
            <span style={{ fontFamily: "'Fraunces', serif", fontWeight: 900, fontSize: 14, color: palette.oceanDark }}>
              {(item.ticker || "?").slice(0, 1)}
            </span>
          )}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              fontFamily: "'Fraunces', serif",
              fontWeight: 700,
              fontSize: 13.5,
              color: palette.oceanDark,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              lineHeight: 1.15,
            }}
          >
            {item.name || item.ticker}
          </div>
          <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 11, fontWeight: 600, color: palette.ink, opacity: 0.6, lineHeight: 1.1 }}>
            {item.ticker}
          </div>
        </div>
        <div style={{ flexShrink: 0, display: "flex", alignItems: "baseline", gap: 8, justifyContent: "flex-end" }}>
          {item.loading ? (
            <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 12, color: palette.ink, opacity: 0.6 }}>{"…"}</span>
          ) : priceText ? (
            <>
              {!item.gold && (item.session === "pre" || item.session === "post") && (
                <span
                  style={{
                    fontFamily: "'Outfit', sans-serif",
                    fontWeight: 800,
                    fontSize: 9,
                    letterSpacing: "0.04em",
                    lineHeight: 1,
                    padding: "2px 5px",
                    borderRadius: 5,
                    alignSelf: "center",
                    color: item.session === "pre" ? "#92400E" : "#5B21B6",
                    background: item.session === "pre" ? "#FDE68A" : "#DDD6FE",
                  }}
                  title={item.session === "pre" ? "Pre-market price" : "After-hours price"}
                >
                  {item.session === "pre" ? "PRE" : "AFT"}
                </span>
              )}
              <span style={{ fontFamily: "'Fraunces', serif", fontWeight: 900, fontSize: 14, color: item.gold ? palette.oceanDark : palette.ink }}>
                {priceText}
              </span>
              {pct != null && (
                <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 11.5, fontWeight: 700, color: changeColor, minWidth: 50, textAlign: "right", opacity: flat ? 0.65 : 1 }}>
                  {flat ? "" : up ? "▲" : "▼"}{(pct > 0 ? "+" : "") + pct.toFixed(pctDigits) + "%"}
                </span>
              )}
            </>
          ) : item.gold ? (
            <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 12, fontWeight: 700, color: "#8a5a00" }}>tap {"›"}</span>
          ) : item.noAft ? (
            <span
              style={{ fontFamily: "'Outfit', sans-serif", fontSize: 11.5, fontWeight: 700, color: "#5B21B6", opacity: 0.75 }}
              title="This one didn't trade after hours"
            >
              no after-hours
            </span>
          ) : (
            <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 12, color: palette.ink, opacity: 0.5 }}>{"—"}</span>
          )}
        </div>
      </div>
    </div>
  );
}

function WatchlistScreen({ favs, onPick, onBack, onAdd, onRemove, onAsk, getCards, getBtc, onReorder }) {
  const [cards, setCards] = useState({});
  const [dragTicker, setDragTicker] = useState(null);
  const [dragOrder, setDragOrder] = useState(null);
  const dragStartY = useRef(0);
  const dragFrom = useRef(0);
  const dragPitch = useRef(49);
  const dragActive = useRef(false);
  const dragOrderRef = useRef(null);
  const [btc, setBtc] = useState(null);
  const [btcErr, setBtcErr] = useState(false);
  const [entry, setEntry] = useState("");
  const [hint, setHint] = useState("");
  const [sortKey, setSortKey] = useState("order");
  const [sortAsc, setSortAsc] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  // Which price each row shows: "mc" = the 4pm market close, "aft" = the
  // after-hours print. The worker sends both legs, so flipping this is instant.
  const [priceMode, setPriceMode] = useState("mc");
  const loadSeq = useRef(0);
  const applyCards = (list) => {
    const byTicker = {};
    (list || []).forEach((c) => { if (c && c.ticker) byTicker[String(c.ticker).toUpperCase()] = { loading: false, ...c }; });
    setCards((prev) => {
      const next = { ...prev };
      Object.keys(byTicker).forEach((t) => { next[t] = byTicker[t]; });
      return next;
    });
    return byTicker;
  };
  const loadAll = async (isRefresh) => {
    const seq = ++loadSeq.current;
    const list = favs || [];
    if (isRefresh) {
      setRefreshing(true);
      if (getBtc) getBtc().then((r) => { if (seq === loadSeq.current) { setBtc(r); setBtcErr(false); } }).catch(() => { if (seq === loadSeq.current) setBtcErr(true); });
    }
    setCards((prev) => {
      const next = { ...prev };
      list.forEach((s) => { if (isRefresh || !next[s]) next[s] = { loading: true, ticker: s }; });
      return next;
    });
    // Fetch, then re-try ONLY the tickers that came back without a price. The
    // free data tier occasionally drops a few under load; a short pause clears it.
    let missing = list.slice();
    for (let attempt = 0; attempt < 3 && missing.length; attempt++) {
      if (attempt > 0) await new Promise((r) => setTimeout(r, 1600));
      if (seq !== loadSeq.current) return;
      let cardList = [];
      try { const res = await getCards(missing); cardList = (res && res.cards) || []; } catch (e) { cardList = []; }
      if (seq !== loadSeq.current) return;
      const got = applyCards(cardList);
      missing = missing.filter((s) => !(got[s] && typeof got[s].price === "number"));
    }
    if (seq === loadSeq.current) {
      setCards((prev) => {
        const next = { ...prev };
        list.forEach((s) => { if (next[s] && next[s].loading) next[s] = { loading: false, ticker: s }; });
        return next;
      });
      setRefreshing(false);
    }
  };
  useEffect(() => {
    loadAll(false);
    return () => { loadSeq.current++; };
  }, [favs]);
  useEffect(() => {
    let alive = true;
    if (!getBtc) return;
    const pull = () => {
      getBtc().then((r) => { if (alive) { setBtc(r); setBtcErr(false); } }).catch(() => { if (alive) setBtcErr(true); });
    };
    pull();
    // Bitcoin trades around the clock — keep it ticking without a manual refresh.
    const id = setInterval(pull, 30000);
    return () => { alive = false; clearInterval(id); };
  }, []);
  const submitLook = () => {
    const sym = entry.trim().toUpperCase();
    if (sym) onPick(sym);
  };
  const submitAdd = () => {
    const msg = onAdd ? onAdd(entry) : "";
    setHint(msg || "");
    if (!msg) setEntry("");
  };
  const chooseSort = (k) => {
    if (k === sortKey) setSortAsc((v) => !v);
    else { setSortKey(k); setSortAsc(k === "ticker"); }
  };
  // Swap in whichever leg the MC/AFT toggle is on. Done before sorting so "Price"
  // and "% Chg" sort on what's actually on screen. A ticker with no after-hours
  // print (thinly traded, or the Finnhub fallback filled the row) shows a dash
  // rather than quietly falling back to the close and looking like a real AFT price.
  const inMode = (c) => {
    if (!c || c.loading || c.gold) return c;
    if (priceMode === "aft") {
      if (!c.post || typeof c.post.price !== "number") return { ...c, price: null, change: null, changePct: null, session: "post", noAft: true };
      // change (dollars) stays null: it's the regular-session figure, and the
      // up/down arrow would point the wrong way if the after-hours % is missing.
      return { ...c, price: c.post.price, change: null, changePct: c.post.changePct, session: "post" };
    }
    if (!c.regular || typeof c.regular.price !== "number") return { ...c, session: "regular" };
    return { ...c, price: c.regular.price, changePct: c.regular.changePct, session: "regular" };
  };
  let ordered = (favs || []).map((s) => inMode(cards[s] || { ticker: s, loading: true }));
  if (sortKey !== "order") {
    ordered = ordered.slice().sort((a, b) => {
      if (sortKey === "ticker") {
        const r = String(a.ticker).localeCompare(String(b.ticker));
        return sortAsc ? r : -r;
      }
      const key = sortKey === "price" ? "price" : "changePct";
      const an = typeof a[key] === "number";
      const bn = typeof b[key] === "number";
      if (!an && !bn) return 0;
      if (!an) return 1;
      if (!bn) return -1;
      return sortAsc ? a[key] - b[key] : b[key] - a[key];
    });
  }
  const btcItem = {
    ticker: "BTC",
    name: "Bitcoin",
    gold: true,
    loading: !btc && !btcErr,
    price: btc ? btc.price : null,
    changePct: btc ? btc.changePct : null,
  };
  const SORTS = [["order", "My order"], ["ticker", "Ticker"], ["price", "Price"], ["change", "% Chg"]];
  // Drag-to-reorder (only meaningful in "My order"). The dragged ticker follows
  // the finger by whole-row steps; on release we persist the new order.
  const startReorder = (ticker, clientY, el) => {
    const base = (favs || []).slice();
    dragFrom.current = base.indexOf(ticker);
    dragStartY.current = clientY;
    let h = 44;
    try { const row = el && el.closest ? el.closest("[data-wl-row]") : null; if (row && row.offsetHeight) h = row.offsetHeight; } catch (e) {}
    dragPitch.current = h + 5; // 5px flex gap between rows
    dragActive.current = true;
    dragOrderRef.current = base;
    setDragTicker(ticker);
    setDragOrder(base);
  };
  const moveReorder = (clientY) => {
    if (!dragActive.current) return;
    const base = (favs || []).slice();
    const ticker = base[dragFrom.current];
    if (!ticker) return;
    const steps = Math.round((clientY - dragStartY.current) / dragPitch.current);
    const to = Math.max(0, Math.min(base.length - 1, dragFrom.current + steps));
    const without = base.filter((t) => t !== ticker);
    without.splice(to, 0, ticker);
    dragOrderRef.current = without;
    setDragOrder(without);
  };
  const endReorder = () => {
    if (!dragActive.current) return;
    dragActive.current = false;
    const finalOrder = dragOrderRef.current;
    dragOrderRef.current = null;
    if (finalOrder && onReorder) onReorder(finalOrder);
    setDragTicker(null);
    setDragOrder(null);
  };
  const reorderable = sortKey === "order";
  let renderList = ordered;
  if (dragTicker && dragOrder) renderList = dragOrder.map((s) => inMode(cards[s] || { ticker: s, loading: true }));
  return (
    <div
      className="screen screen-analyzer"
      style={{
        background: `linear-gradient(180deg, ${palette.sky} 0%, ${palette.sand} 55%, ${palette.sandDeep} 100%)`,
        paddingTop: 20,
      }}
    >
      <style>{FONTS}</style>
      <div style={{ maxWidth: 620, margin: "0 auto" }}>
        <button
          onClick={onBack}
          style={{
            fontFamily: "'Outfit', sans-serif",
            fontWeight: 600,
            fontSize: 14,
            color: palette.oceanDark,
            background: "transparent",
            border: "none",
            cursor: "pointer",
            padding: 0,
            marginBottom: 10,
          }}
        >
          {"←"} Back to the beach
        </button>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginBottom: 10 }}>
          <h1
            style={{
              fontFamily: "'Fraunces', serif",
              fontWeight: 900,
              fontSize: "clamp(24px, 5.5vw, 30px)",
              color: palette.oceanDark,
              margin: 0,
            }}
          >
            {"📋"} Watchlist
          </h1>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <button
              onClick={() => setPriceMode((m) => (m === "mc" ? "aft" : "mc"))}
              aria-label={priceMode === "aft" ? "Showing after-hours prices. Tap for market close prices." : "Showing market close prices. Tap for after-hours prices."}
              title={priceMode === "aft" ? "Showing after-hours prices — tap for the market close" : "Showing market close prices — tap for after-hours"}
              style={{
                fontFamily: "'Outfit', sans-serif",
                fontWeight: 800,
                fontSize: 12.5,
                letterSpacing: "0.04em",
                color: priceMode === "aft" ? palette.white : palette.oceanDark,
                background: priceMode === "aft" ? "#6D28D9" : "rgba(255,255,255,0.85)",
                border: `2px solid ${priceMode === "aft" ? "#6D28D9" : palette.ocean}`,
                borderRadius: 999,
                height: 38,
                padding: "0 13px",
                cursor: "pointer",
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {priceMode === "aft" ? "AFT" : "MC"}
            </button>
            <button
              onClick={() => loadAll(true)}
              disabled={refreshing}
              aria-label="Refresh prices"
              title="Refresh prices"
              style={{
                fontFamily: "'Outfit', sans-serif",
                fontWeight: 700,
                fontSize: 16,
                color: palette.oceanDark,
                background: "rgba(255,255,255,0.85)",
                border: `2px solid ${palette.ocean}`,
                borderRadius: 999,
                width: 38,
                height: 38,
                cursor: refreshing ? "default" : "pointer",
                opacity: refreshing ? 0.5 : 1,
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {"↻"}
            </button>
            {onAsk && (
              <button
                onClick={onAsk}
                style={{
                  fontFamily: "'Outfit', sans-serif",
                  fontWeight: 700,
                  fontSize: 13.5,
                  color: palette.white,
                  background: `linear-gradient(180deg, ${palette.coral}, ${palette.coralDark})`,
                  border: "none",
                  borderRadius: 999,
                  padding: "8px 16px",
                  cursor: "pointer",
                  whiteSpace: "nowrap",
                  boxShadow: "0 4px 12px rgba(194,75,55,0.3)",
                }}
              >
                {"✨"} Ask AI
              </button>
            )}
          </div>
        </div>
        {priceMode === "aft" && (
          <div
            style={{
              fontFamily: "'Outfit', sans-serif",
              fontSize: 12.5,
              fontWeight: 600,
              color: "#5B21B6",
              background: "#EDE9FE",
              border: "1px solid #C4B5FD",
              borderRadius: 10,
              padding: "6px 10px",
              marginBottom: 10,
              lineHeight: 1.35,
            }}
          >
            Showing after-hours prices. The % is the move since the 4pm close. Tap {"AFT"} again for closing prices.
          </div>
        )}
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: hint ? 8 : 10 }}>
          <input
            value={entry}
            onChange={(e) => { setEntry(e.target.value.toUpperCase()); if (hint) setHint(""); }}
            onKeyDown={(e) => e.key === "Enter" && submitLook()}
            autoCapitalize="characters"
            autoCorrect="off"
            spellCheck={false}
            enterKeyHint="search"
            placeholder="Enter a ticker — AAPL, TSLA…"
            style={{
              flex: "1 1 180px",
              fontFamily: "'Outfit', sans-serif",
              fontSize: 16,
              fontWeight: 600,
              letterSpacing: "0.05em",
              padding: "10px 14px",
              borderRadius: 12,
              border: `2px solid ${palette.ocean}`,
              background: palette.white,
              color: palette.ink,
              outline: "none",
            }}
          />
          <button
            onClick={submitLook}
            disabled={!entry.trim()}
            style={{
              fontFamily: "'Outfit', sans-serif",
              fontWeight: 700,
              fontSize: 15,
              color: palette.white,
              background: !entry.trim() ? "#9DB8C0" : `linear-gradient(180deg, ${palette.ocean}, ${palette.oceanDark})`,
              border: "none",
              borderRadius: 12,
              padding: "10px 16px",
              cursor: !entry.trim() ? "default" : "pointer",
            }}
          >
            Look it up
          </button>
          <button
            onClick={submitAdd}
            aria-label="Add this ticker to your watchlist"
            title="Add to your watchlist"
            style={{
              fontFamily: "'Outfit', sans-serif",
              fontWeight: 700,
              fontSize: 17,
              color: palette.oceanDark,
              background: "rgba(255,255,255,0.85)",
              border: `2px solid ${palette.ocean}`,
              borderRadius: 12,
              padding: "10px 14px",
              cursor: "pointer",
            }}
          >
            +
          </button>
        </div>
        {hint && (
          <div style={{ fontFamily: "'Outfit', sans-serif", fontSize: 13, color: palette.oceanDark, marginBottom: 8 }}>
            {hint}
          </div>
        )}
        <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap", marginBottom: 10 }}>
          <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 11.5, fontWeight: 700, color: palette.ink, opacity: 0.55 }}>Sort</span>
          {SORTS.map(([k, label]) => (
            <button
              key={k}
              onClick={() => chooseSort(k)}
              style={{
                fontFamily: "'Outfit', sans-serif",
                fontWeight: 700,
                fontSize: 11.5,
                color: sortKey === k ? palette.white : palette.oceanDark,
                background: sortKey === k ? palette.ocean : "rgba(255,255,255,0.7)",
                border: `1.5px solid ${palette.ocean}`,
                borderRadius: 999,
                padding: "3px 10px",
                cursor: "pointer",
              }}
            >
              {label}{sortKey === k && k !== "order" ? (sortAsc ? " ↑" : " ↓") : ""}
            </button>
          ))}
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
          <WatchRow item={btcItem} onPick={onPick} />
          {renderList.map((it) => (
            <WatchRow
              key={it.ticker}
              item={it}
              onPick={onPick}
              onRemove={onRemove}
              reorderable={reorderable}
              isReordering={it.ticker === dragTicker}
              onReorderStart={startReorder}
              onReorderMove={moveReorder}
              onReorderEnd={endReorder}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

function BtcBadge({ getBtc }) {
  const [d, setD] = useState(null);
  const [err, setErr] = useState(false);
  useEffect(() => {
    let alive = true;
    if (!getBtc) return;
    const pull = () => {
      getBtc().then((r) => { if (alive) { setD(r); setErr(false); } }).catch(() => { if (alive && !d) setErr(true); });
    };
    pull();
    // Bitcoin trades 24/7, so keep it live instead of freezing at first load.
    const id = setInterval(pull, 30000);
    return () => { alive = false; clearInterval(id); };
  }, []);
  const up = d && typeof d.changePct === "number" ? d.changePct >= 0 : null;
  return (
    <div
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 9,
        background: "rgba(255,255,255,0.72)",
        border: "1.5px solid #D9A400",
        borderRadius: 999,
        padding: "7px 15px",
        marginBottom: 22,
        boxShadow: "0 4px 14px rgba(21,94,117,0.15)",
      }}
    >
      <span
        style={{
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          width: 24,
          height: 24,
          borderRadius: "50%",
          background: "#F7C948",
          color: "#8a5a00",
          fontWeight: 900,
          fontSize: 15,
        }}
      >
        {"\u20bf"}
      </span>
      <span style={{ fontFamily: "'Outfit', sans-serif", fontWeight: 700, fontSize: 14, color: palette.ink }}>
        Bitcoin
      </span>
      {d && typeof d.price === "number" ? (
        <>
          <span style={{ fontFamily: "'Fraunces', serif", fontWeight: 900, fontSize: 16, color: palette.oceanDark }}>
            ${d.price.toLocaleString(undefined, { maximumFractionDigits: 0 })}
          </span>
          {typeof d.changePct === "number" && (
            <span style={{ fontFamily: "'Outfit', sans-serif", fontWeight: 700, fontSize: 13, color: up ? palette.palm : palette.red }}>
              {up ? "\u25b2" : "\u25bc"} {(d.changePct >= 0 ? "+" : "") + d.changePct.toFixed(1)}%
            </span>
          )}
        </>
      ) : err ? (
        <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 13, color: palette.ink, opacity: 0.55 }}>price unavailable</span>
      ) : (
        <span style={{ fontFamily: "'Outfit', sans-serif", fontSize: 13, color: palette.ink, opacity: 0.55 }}>loading{"\u2026"}</span>
      )}
    </div>
  );
}

function AskScreen({ askAI, onBack }) {
  const [q, setQ] = useState("");
  const [answer, setAnswer] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const ask = async () => {
    const question = q.trim();
    if (!question || loading) return;
    setLoading(true);
    setError("");
    setAnswer("");
    try {
      const text = await askAI(question);
      const clean = (text || "").replace(/\*\*/g, "").replace(/^#+\s*/gm, "").trim();
      setAnswer(clean || "No answer came back — try rephrasing.");
    } catch (e) {
      setError("Couldn't reach the AI just now. Give it another try in a moment.");
    } finally {
      setLoading(false);
    }
  };
  return (
    <div
      className="screen screen-analyzer"
      style={{
        background: `linear-gradient(180deg, ${palette.sky} 0%, ${palette.sand} 55%, ${palette.sandDeep} 100%)`,
        paddingTop: 20,
      }}
    >
      <style>{FONTS}</style>
      <div style={{ maxWidth: 680, margin: "0 auto" }}>
        <button
          onClick={onBack}
          style={{
            fontFamily: "'Outfit', sans-serif",
            fontWeight: 600,
            fontSize: 14,
            color: palette.oceanDark,
            background: "transparent",
            border: "none",
            cursor: "pointer",
            padding: 0,
            marginBottom: 12,
          }}
        >
          {"←"} Back to watchlist
        </button>
        <h1 style={{ fontFamily: "'Fraunces', serif", fontWeight: 900, fontSize: "clamp(26px, 6vw, 36px)", color: palette.oceanDark, margin: "0 0 4px" }}>
          {"✨"} Ask AI
        </h1>
        <p style={{ fontFamily: "'Outfit', sans-serif", fontSize: 15, color: palette.ink, opacity: 0.85, margin: "0 0 16px", lineHeight: 1.5 }}>
          Ask anything {"—"} markets, a company, an idea. Answers pull from live web research.
        </p>
        <textarea
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) ask(); }}
          placeholder="e.g. What's driving semiconductor stocks this week?"
          rows={3}
          style={{
            width: "100%",
            boxSizing: "border-box",
            fontFamily: "'Outfit', sans-serif",
            fontSize: 16,
            fontWeight: 500,
            padding: "14px 16px",
            borderRadius: 14,
            border: `2px solid ${palette.ocean}`,
            background: palette.white,
            color: palette.ink,
            outline: "none",
            resize: "vertical",
            lineHeight: 1.4,
          }}
        />
        <button
          onClick={ask}
          disabled={loading || !q.trim()}
          style={{
            marginTop: 10,
            fontFamily: "'Outfit', sans-serif",
            fontWeight: 700,
            fontSize: 16,
            color: palette.white,
            background: loading || !q.trim() ? "#9DB8C0" : `linear-gradient(180deg, ${palette.coral}, ${palette.coralDark})`,
            border: "none",
            borderRadius: 999,
            padding: "12px 28px",
            cursor: loading || !q.trim() ? "default" : "pointer",
          }}
        >
          {loading ? "Thinking…" : "✨ Ask"}
        </button>
        {error && (
          <div style={{ marginTop: 16, fontFamily: "'Outfit', sans-serif", fontSize: 15, color: palette.coralDark, background: "rgba(255,255,255,0.8)", border: `2px solid ${palette.coral}`, borderRadius: 14, padding: "14px 18px" }}>
            {error}
          </div>
        )}
        {answer && !loading && (
          <div style={{ marginTop: 18, fontFamily: "'Outfit', sans-serif", fontSize: 15.5, color: palette.ink, lineHeight: 1.6, background: "rgba(255,255,255,0.85)", borderRadius: 16, padding: "18px 20px", whiteSpace: "pre-wrap" }}>
            {answer}
          </div>
        )}
        <div style={{ marginTop: 16, fontFamily: "'Outfit', sans-serif", fontSize: 12, color: palette.ink, opacity: 0.5 }}>
          Powered by Perplexity {"·"} not financial advice
        </div>
      </div>
    </div>
  );
}

function MarketBadges({ getIndexes }) {
  const [d, setD] = useState(null);
  useEffect(() => {
    let alive = true;
    if (getIndexes) {
      getIndexes().then((r) => { if (alive) setD(r); }).catch(() => {});
    }
    return () => { alive = false; };
  }, []);
  const cell = (label, obj) => {
    if (!obj || typeof obj.price !== "number") return null;
    const up = typeof obj.changePct === "number" ? obj.changePct >= 0 : null;
    return (
      <span style={{ display: "inline-flex", alignItems: "baseline", gap: 5 }}>
        <span style={{ fontFamily: "'Outfit', sans-serif", fontWeight: 700, fontSize: 12, color: palette.ink, opacity: 0.7 }}>{label}</span>
        <span style={{ fontFamily: "'Fraunces', serif", fontWeight: 900, fontSize: 13.5, color: palette.oceanDark }}>
          {obj.price.toLocaleString(undefined, { maximumFractionDigits: 0 })}
        </span>
        {typeof obj.changePct === "number" && (
          <span style={{ fontFamily: "'Outfit', sans-serif", fontWeight: 700, fontSize: 11.5, color: up ? palette.palm : palette.red }}>
            {up ? "▲" : "▼"}{(obj.changePct >= 0 ? "+" : "") + obj.changePct.toFixed(1)}%
          </span>
        )}
      </span>
    );
  };
  const dow = d && cell("Dow", d.dow);
  const nasdaq = d && cell("Nasdaq", d.nasdaq);
  if (!dow && !nasdaq) return null;
  return (
    <div
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 18,
        flexWrap: "wrap",
        justifyContent: "center",
        marginTop: -12,
        marginBottom: 20,
      }}
    >
      {dow}
      {nasdaq}
    </div>
  );
}

